import { writeFileSync } from 'node:fs'; import { dirname, join } from 'node:path'; import { fileURLToPath } from 'node:url'; const HERE = dirname(fileURLToPath(import.meta.url)); import { countNodes } from '../../harness/large-map/fixtures.mjs'; import { encodeBackup } from '../../../src/engine/hypertree/persistence/backup.js'; import { createInternalPolicyContext } from '../../../src/engine/hypertree/edition/index.js';
const PNG=Uint8Array.from(atob('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII='),(c)=>c.charCodeAt(0));
function pdf(){const s='BT /F1 18 Tf 20 100 Td (Sample PDF) Tj ET',objs=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 200 200] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>','<< /Length '+s.length+' >>\nstream\n'+s+'\nendstream','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'];let b='%PDF-1.4\n';const off=[];objs.forEach((o,i)=>{off.push(b.length);b+=(i+1)+' 0 obj\n'+o+'\nendobj\n'});const x=b.length;b+='xref\n0 6\n0000000000 65535 f \n';for(const o of off)b+=String(o).padStart(10,'0')+' 00000 n \n';b+='trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n'+x+'\n%%EOF\n';return new TextEncoder().encode(b)}
const reg=new Map(); [['att-text','샘플-텍스트.txt','text/plain',new TextEncoder().encode('sample text content')],['att-image','샘플-이미지.png','image/png',PNG],['att-pdf','샘플-PDF.pdf','application/pdf',pdf()],['att-empty','빈-파일.txt','text/plain',new Uint8Array(0)]].forEach(([id,name,type,bytes])=>{const file=new File([bytes],name,{type});reg.set(id,{file,metadata:{attachmentId:id,originalName:name,sizeBytes:file.size,mime:type,classification:{format:type.split('/')[1],badge:type==='application/pdf'?'PDF':'FILE',mime:type,needsReview:false}}})});
[['dup-a','same-name.txt','text/plain','alpha attachment'],['dup-b','same-name.txt','text/plain','beta attachment']].forEach(([id,name,type,text])=>{const file=new File([new TextEncoder().encode(text)],name,{type});reg.set(id,{file,metadata:{attachmentId:id,originalName:name,sizeBytes:file.size,mime:type,classification:{format:'plain',badge:'FILE',mime:type,needsReview:false}}})});
const names=['01_기획','02_연구','03_개발','04_디자인','05_마케팅','06_영업','07_재무','08_인사','09_운영','10_품질','11_보안','12_고객지원','13_교육','14_법무','15_제품','16_데이터','17_인프라','18_문서','19_프로젝트','20_보관'];
function build(total){const root={id:'root',kind:'folder',name:'20개 카테고리 지도',data:{},children:[]};let seq=0;for(let i=0;i<20;i++){const cat={id:'cat-'+(i+1),kind:'folder',name:names[i],data:{},children:[]};root.children.push(cat)}if (total > 300) { const first = root.children[0]; first.children.push({ id:'nested-1', kind:'folder', name:'하위-폴더', data:{}, children:[{ id:'nested-file-1', kind:'file', name:'중첩-문서.txt', data:{}, children:[] }] }); }
root.children.push({id:'root-file',kind:'file',name:'README-root.md',data:{},children:[]});let remaining=total-22-(total>300?2:0);let idx=0;while(remaining>0){const cat=root.children[idx%20];const n=cat.children.length;const ext=['pdf','txt','md','png'][(n+i0(idx))%4];const name=(n%5===0?'보고서':n%5===1?'본문':n%5===2?'정리':n%5===3?'샘플':'메모')+'-'+String(idx+1).padStart(3,'0')+'.'+ext;const id='f-'+seq++;const data={};if(ext==='pdf'&&seq%7===0)data.attachmentId='att-pdf';if(ext==='png'&&seq%11===0)data.attachmentId='att-image';if(ext==='txt'&&seq===1)data.attachmentId='att-text';if(ext==='txt'&&seq===2)data.attachmentId='att-empty';cat.children.push({id,kind:'file',name,data,children:[]});remaining--;idx++}if(total===1000){const a=root.children[0].children.find(x=>x.kind==='file');const b=root.children[1].children.find(x=>x.kind==='file');a.name='same-name.txt';a.data={attachmentId:'dup-a'};b.name='same-name.txt';b.data={attachmentId:'dup-b'}}return root}
function i0(x){return x%4}
const paid=createInternalPolicyContext({edition:'paid'});
for(const count of [300,301,400,500,600,700,800,900,1000]){const tree=build(count);if(countNodes(tree)!==count)throw Error('count '+countNodes(tree));const enc=await encodeBackup({tree,registry:reg,mapName:'FileOrbit-'+count,policyContext:paid,cryptoApi:globalThis.crypto});const bytes=new Uint8Array(await enc.blob.arrayBuffer());writeFileSync(join(HERE, 'FileOrbit-'+count+'.orbit'), bytes);console.log(count,bytes.length)}






